/* 학습 해설
 * Match Wildcard·별표 후보 재시도
 * 단순 wildcard의 별표가 여러 길이를 시도하는 과정을 상태 포인터로 표현하는 실제 helper를 읽습니다.
 * ?는 한 문자를 소비하고 *는 현재 문자열 위치와 그 뒤 패턴 위치를 재시도 지점으로 기록합니다. 일반 문자가 다르고 이전 *가 있으면 그 별표가 소비할 문자열을 한 문자 늘려 다시 비교합니다. 문자열이 끝난 뒤에는 남은 *를 한 개만 건너뛰고 패턴 끝인지 확인합니다. 따라서 이 구현을 모든 glob 문법과 동등한 정규화 엔진으로 설명하지 않습니다. [] 문자 집합·escape 등의 별도 해석은 이 switch에 없습니다.
 * match_wildcard("a*b","axxb")의 포인터 이동을 추적하고 실패 후 별표가 얼마나 더 소비하는지 적습니다. 필요한 문법에 이 helper가 맞는지 판단하며 lib/glob.c의 다른 matcher를 같은 구현으로 취급하지 않습니다. 빈 입력과 연속 * 등 경계 동작은 실제 함수로 확인합니다.
 */
bool match_wildcard(const char *pattern, const char *str)
{
	const char *s = str;
	const char *p = pattern;
	bool star = false;

	while (*s) {
		switch (*p) {
		case '?':
			s++;
			p++;
			break;
		case '*':
			star = true;
			str = s;
			if (!*++p)
				return true;
			pattern = p;
			break;
		default:
			if (*s == *p) {
				s++;
				p++;
			} else {
				if (!star)
					return false;

/* 학습 해설
 * Bootconfig XBC·Index 기반 설정 트리
 * 한 줄 command line에 담기 어려운 계층형 부팅 설정을 작은 node 배열과 문자열 offset으로 관리하는 구조를 익힙니다.
 * XBC node는 16bit next·child·parent·data 필드를 가지며 다른 node는 포인터 대신 배열 index로 연결합니다. data의 상위 bit XBC_VALUE로 key/value를 구분하고 나머지 bit는 복사한 설정 문자열의 offset입니다. Key의 첫 child가 value일 수 있고 그 next는 subkey입니다. Value 배열은 child로 다음 value를 연결하므로 일반 key sibling 연결과 다릅니다. a.b.c 검색은 각 key 이름과 점 경계를 맞추고 child/subkey로 내려갑니다.
 * kernel.trace.mode와 중괄호 kernel { trace { mode = value; } }를 같은 key 경로로 그립니다. xbc_node_get_data와 find_subkey/find_value를 함께 읽습니다. Node 문자열은 XBC가 관리하는 버퍼 안에 있으므로 xbc_exit 이후 보관 포인터를 쓰지 않습니다. 유효 node와 key/value 종류를 확인한 뒤 순회 helper를 선택합니다.
 */
xbc_node_find_subkey(struct xbc_node *parent, const char *key)
{
	struct xbc_node *node;

	if (parent)
		node = xbc_node_get_subkey(parent);
	else
		node = xbc_root_node();

	while (node && xbc_node_is_key(node)) {
		if (!xbc_node_match_prefix(node, &key))
			node = xbc_node_get_next(node);
		else if (*key != '\0')
			node = xbc_node_get_subkey(node);
		else
			break;
	}

	return node;
}

/**
 * xbc_node_find_value() - Find a value node which matches given key
 * @parent: An XBC node.
 * @key: A key string.
 * @vnode: A container pointer of found XBC node.
 *
 * Search a value node under @parent whose (parent) key node matches @key,
 * store it in *@vnode, and returns the value string.
 * The @key can contain several words jointed with '.'. If @parent is NULL,
 * this searches the node from whole tree. Return the value string if a
 * matched key found, return NULL if no node is matched.
 * Note that this returns 0-length string and stores NULL in *@vnode if the
 * key has no value. And also it will return the value of the first entry if
 * the value is an array.
