/* 학습 해설
 * Bootconfig Parser·추가와 대체 연산
 * 설정 값을 한 번 정의하는 것, 배열에 더하는 것, 기존 값을 교체하는 것의 차이를 parser의 연결 변경으로 배웁니다.
 * 점으로 나뉜 key를 계층 node로 만들거나 기존 key를 찾아 값 node를 첫 child로 놓습니다. =는 기존 값이 있으면 Value is redefined 오류입니다. +=는 기존 배열의 마지막 value 아래에 값을 추가합니다. :=는 첫 value node를 새 값으로 초기화하며 기존 subkey 연결 next를 보존하고 기존 배열 child 연결을 끊습니다. Comma는 배열, 중괄호는 계층, #는 줄 주석입니다. 큰따옴표와 작은따옴표는 내부 공백을 보존하지만 같은 따옴표 escape 기능은 없습니다.
 * 작은 읽기 전용 설정 예 key=bar,baz 뒤 key+=qux와 key:=qux를 비교합니다. 실제 부팅 설정을 바꾸는 대신 원본 도구와 임시 파일에서 구문을 검사합니다. 문법에 맞는 key라도 실제 설정을 소비하는 subsystem의 허용 옵션인지까지 parser가 검사하지는 않습니다.
 */
static int __init xbc_parse_kv(char **k, char *v, int op)
{
	struct xbc_node *prev_parent = last_parent;
	struct xbc_node *child;
	char *next;
	int c, ret;

	ret = __xbc_parse_keys(*k);
	if (ret)
		return ret;

	c = __xbc_parse_value(&v, &next);
	if (c < 0)
		return c;

	child = xbc_node_get_child(last_parent);
	if (child && xbc_node_is_value(child)) {
		if (op == '=')
			return xbc_parse_error("Value is redefined", v);
		if (op == ':') {
			unsigned short nidx = child->next;

			xbc_init_node(child, v, XBC_VALUE);
			child->next = nidx;	/* keep subkeys */
