/* 학습 해설
 * Bootconfig Init·복사와 검증 및 정리
 * 복잡한 초기 설정을 읽다가 실패하더라도 이전에 할당한 자료를 정리하고 다음 호출의 상태를 일관되게 만드는 경로를 배웁니다.
 * 이미 xbc_data가 있으면 EBUSY입니다. 크기 0 또는 상한 초과를 거부한 다음 size+1 버퍼를 할당·복사하고 마지막 NUL을 붙입니다. Node 배열을 할당해 0으로 초기화하고 parse_tree 뒤 verify_tree로 미닫힌 brace·빈 트리·깊이·key 길이를 검사합니다. 실패하면 오류 문구·위치를 기록한 뒤 _xbc_exit(true)로 두 할당과 전역 상태를 정리합니다. 성공 반환은 0이 아니라 양수 node 수입니다. 커널 초기 경로는 memblock, 공식 tools 경로는 malloc/free를 사용합니다.
 * xbc_init의 양수 성공·음수 errno와 epos=-1인 비parser 오류를 구분합니다. 재초기화 전 xbc_exit가 필요하고 반환 node·문자열을 정리 후 사용하지 않습니다. 입력 buffer를 복사하므로 입력 자체와 관리되는 XBC buffer의 수명도 분리합니다. 공식 도구의 parser sanity test로 경계 예를 확인합니다.
 */
int __init xbc_init(const char *data, size_t size, const char **emsg, int *epos)
{
	int ret;

	if (epos)
		*epos = -1;

	if (xbc_data) {
		if (emsg)
			*emsg = "Bootconfig is already initialized";
		return -EBUSY;
	}
	if (size > XBC_DATA_MAX || size == 0) {
		if (emsg)
			*emsg = size ? "Config data is too big" :
				"Config data is empty";
		return -ERANGE;
	}

	xbc_data = xbc_alloc_mem(size + 1);
	if (!xbc_data) {
		if (emsg)
			*emsg = "Failed to allocate bootconfig data";
		return -ENOMEM;
	}
	memcpy(xbc_data, data, size);

/* 학습 해설
 * Bootconfig Footer·Initrd 뒤 크기와 Checksum
 * 부팅 이미지를 풀지 않고 끝부분에서 추가 설정을 찾도록 자료 길이·검사합·magic을 붙이는 파일 형식을 배웁니다.
 * 공식 도구는 설정 text와 종료 NUL을 읽고 parser로 검증한 뒤 기존 footer가 있으면 제거합니다. 원래 image 길이+설정 길이+20바이트 footer를 4바이트 경계로 맞추는 zero padding을 설정 뒤에 넣습니다. Footer에는 padding 포함 설정 size와 바이트 합 checksum을 little-endian u32로 쓰고 12바이트 #BOOTCONFIG 및 newline magic을 붙입니다. Checksum은 암호학적 인증이 아니라 바이트 합입니다. 읽는 쪽은 끝 magic·size·checksum과 구문을 확인합니다.
 * Linux/WSL의 공식 bootconfig 도구로 일회용 image 복사본에 -a 설정, 조회, -d 제거를 실험합니다. 원래 운영 부팅 image를 실습 대상으로 쓰지 않습니다. 구문 검증이 성공해도 실제 initrd 형식과 옵션 schema까지 검사했다는 보장은 없으며 원본에는 그 검사를 위한 TODO가 있습니다.
