/* 학습 해설
 * BCD·10진 숫자 두 개의 Nibble 표현
 * RTC 같은 장치가 십의 자리와 일의 자리를 각각 4비트로 저장하는 표현을 일반 이진 정수와 구분합니다.
 * BCD 0x42는 상위 nibble 4와 하위 nibble 2이므로 십진 42입니다. bcd2bin은 low nibble+(high nibble×10)을 계산합니다. bin2bcd는 십의 자리 t를 (val×103)>>10으로 계산하고 (t<<4)|(val-t×10)으로 합칩니다. 두 자리 유효 범위 0~99에서는 이 t가 val/10과 맞습니다. Header는 constant 입력의 다른 계산 경로와 각 nibble<10인 유효성 검사를 제공하지만 변환 함수 자체는 오류 값을 반환하지 않습니다.
 * 장치 register가 BCD인지 binary인지 확인하고 유효한 두 자리 값을 변환합니다. bcd_is_valid를 통해 0x1a 같은 잘못된 nibble을 검사합니다. 변환 helper의 반환형과 입력 폭을 지키며 세 자리 이상 값을 이 byte 표현에 그대로 저장하지 않습니다.
 */
unsigned char _bin2bcd(unsigned val)
{
	const unsigned int t = (val * 103) >> 10;

	return (t << 4) | (val - t * 10);
}
EXPORT_SYMBOL(_bin2bcd);

/* 학습 해설
 * Bit Reverse·비트 위치 전체 뒤집기
 * 장치와 bit-oriented 알고리즘에서 가장 앞 비트와 가장 뒤 비트의 순서를 바꾸는 연산을 byte endian 변환과 구분합니다.
 * 일반 runtime 8bit 경로는 256개 byte_rev_table에서 입력 byte의 역순 bit 값을 찾습니다. 16bit는 두 byte를 각각 뒤집고 위치도 교환하며 32bit는 두 16bit의 순서를 바꿉니다. Constant 경로는 16·8·4·2·1bit 단위 교환을 mask와 shift로 수행합니다. CONFIG_HAVE_ARCH_BITREVERSE가 있으면 architecture 구현을 사용할 수 있습니다. bitrev8x4는 32bit 전체 반전과 달리 각 byte 안에서만 bit를 뒤집는 형태입니다.
 * 입력 폭을 고르고 bitrev8/16/32와 bitrev8x4의 계약을 확인합니다. 0x12의 binary 00010010을 종이에 뒤집고 결과를 table과 대조합니다. CRC reflection 같은 소비자의 bit 순서와 연결하되 모든 byte order 변환을 이 함수로 대신하지 않습니다.
 */
static inline u8 __bitrev8(u8 byte)
{
	return byte_rev_table[byte];
}

static inline u16 __bitrev16(u16 x)
{
	return (__bitrev8(x & 0xff) << 8) | __bitrev8(x >> 8);
}

static inline u32 __bitrev32(u32 x)
{
	return (__bitrev16(x & 0xffff) << 16) | __bitrev16(x >> 16);
}

#endif /* CONFIG_HAVE_ARCH_BITREVERSE */

