	___x = (___x >> 16) | (___x << 16);	\
	___x = ((___x & (u32)0xFF00FF00UL) >> 8) | ((___x & (u32)0x00FF00FFUL) << 8);	\
	___x = ((___x & (u32)0xF0F0F0F0UL) >> 4) | ((___x & (u32)0x0F0F0F0FUL) << 4);	\
	___x = ((___x & (u32)0xCCCCCCCCUL) >> 2) | ((___x & (u32)0x33333333UL) << 2);	\

/* 학습 해설
 * CLZ·CTZ Compiler Helper·최상위와 최하위 Bit
 * C 소스에서 직접 호출을 찾지 못하는 함수도 compiler의 builtin 확장에 필요할 수 있다는 점을 실제 runtime helper로 배웁니다.
 * __clzsi2는 32-fls(val), __clzdi2는 64-fls64(val)로 선행 0 수를 계산합니다. CTZ 변형은 __ffs/ __ffs64로 최하위 set bit 위치를 얻습니다. Fls의 1부터 세는 위치와 ffs 계열의 0부터 세는 index를 구분합니다. __weak 심볼은 architecture 구현으로 대체될 수 있습니다. 파일 주석처럼 source 안 직접 호출이 없더라도 compiler builtin을 지원하므로 불필요한 dead code라고 단정할 수 없습니다.
 * nonzero input을 기본 예로 사용해 32bit 8에서 leading 28·trailing 3을 계산합니다. 0에 대한 builtin 계약과 helper가 호출하는 bit 함수의 전제를 구분합니다. Compiler가 helper를 호출하는 대상 architecture와 linking 설정을 확인하며 사용자 C에서 builtin ctz(0)가 정의됐다고 가정하지 않습니다.
 */
int __weak __clzsi2(int val)
{
	return 32 - fls(val);
}
EXPORT_SYMBOL(__clzsi2);

int __weak __clzdi2(u64 val);
int __weak __clzdi2(u64 val)
{
	return 64 - fls64(val);
}
EXPORT_SYMBOL(__clzdi2);

int __weak __ctzdi2(u64 val);
int __weak __ctzdi2(u64 val)
{
	return __ffs64(val);
}
EXPORT_SYMBOL(__ctzdi2);

/* 학습 해설
 * Libgcc Left Shift·두 Word 사이 Carry
 * 32bit 단위로 64bit 값을 옮길 때 낮은 word에서 높은 word로 넘어가는 bit를 명시적으로 합치는 compiler helper를 읽습니다.
 * DWunion은 64bit 값과 두 32bit high/low 표현을 겹쳐 놓습니다. b=0이면 원래 값을 돌려줍니다. bm=32-b가 양수면 low를 b만큼 왼쪽으로 옮기고 low의 상위 b bit를 carry로 high에 OR합니다. b>=32의 유효 shift에서는 low=0이고 원래 low를 b-32만큼 이동해 high를 만듭니다. 결과는 64bit 표현이며 넘어간 bit를 추가 128bit 공간에 보존하지 않습니다.
 * compiler helper의 정상 shift 범위 0~63과 DWstruct의 endian별 field 순서를 확인합니다. 일반 C 코드에서 이 함수를 임의 길이 shift 검증 API로 직접 쓰지 않습니다. high=0·low=1에 b=32를 적용한 뒤 high=1·low=0으로 되는 것을 추적합니다.
 */
long long notrace __ashldi3(long long u, word_type b)
{
	DWunion uu, w;
	word_type bm;

	if (b == 0)
		return u;

	uu.ll = u;
	bm = 32 - b;

	if (bm <= 0) {
		w.s.low = 0;
		w.s.high = (unsigned int) uu.s.low << -bm;
	} else {
		const unsigned int carries = (unsigned int) uu.s.low >> bm;

		w.s.low = (unsigned int) uu.s.low << b;
		w.s.high = ((unsigned int) uu.s.high << b) | carries;
	}

	return w.ll;
}
EXPORT_SYMBOL(__ashldi3);

/* 학습 해설
 * Libgcc Logical Right Shift·Zero Fill
 * 64bit 값의 오른쪽 이동에서 상위에 0을 채우는 논리 shift와 부호 bit를 채우는 산술 shift를 구분합니다.
 * 0<b<32에서 high는 unsigned로 b만큼 오른쪽 이동하고 high의 낮은 b bit는 왼쪽으로 32-b만큼 이동하여 low의 상단에 합칩니다. b>=32에서는 새 high=0이고 원래 high를 unsigned로 b-32만큼 이동해 low에 넣습니다. 반환형 이름이 long long이어도 이 helper의 bit 이동은 logical zero-fill입니다. b=0은 원래 값을 돌려줍니다.
 * 정상 0~63 shift 범위에서 최상위 bit만 1인 64bit 값과 b=1을 추적합니다. 반환 비트 패턴을 unsigned 표현으로 관찰하고 signed arithmetic right shift와 비교합니다. DWunion과 해당 compiler가 이 helper를 선택하는 연산을 확인합니다.
 */
long long notrace __lshrdi3(long long u, word_type b)
{
	DWunion uu, w;
	word_type bm;

	if (b == 0)
		return u;

	uu.ll = u;
	bm = 32 - b;

	if (bm <= 0) {
		w.s.high = 0;
		w.s.low = (unsigned int) uu.s.high >> -bm;
	} else {
		const unsigned int carries = (unsigned int) uu.s.high << bm;

		w.s.high = (unsigned int) uu.s.high >> b;
		w.s.low = ((unsigned int) uu.s.low >> b) | carries;
	}

	return w.ll;
}
EXPORT_SYMBOL(__lshrdi3);

/* 학습 해설
 * Libgcc Arithmetic Right Shift·Sign Fill
 * 음수의 64bit 오른쪽 이동을 두 word로 구현할 때 최상위 부호를 유지하는 방법을 compiler helper로 배웁니다.
 * 0<b<32에서 signed high를 오른쪽으로 옮기며 부호 bit를 보존하고 원래 high의 낮은 bit는 unsigned carry로 low에 합칩니다. b>=32에서는 high>>31로 새 high를 모두 0 또는 모두 1로 채우고 원래 high를 b-32만큼 이동해 low로 보냅니다. 커널과 대상 compiler의 signed shift 규약을 전제로 하는 구현이며 b=0은 입력 그대로입니다.
 * 정상 shift 범위에서 -8을 1bit 이동한 결과 -4와 logical 이동의 다른 비트 패턴을 비교합니다. ISO C의 부호 있는 shift를 아무 문맥 없이 다른 언어·compiler로 옮겨 같은 규약이라고 단정하지 않습니다. 사용자 예제의 signedness와 커널 build 문맥을 확인합니다.
 */
long long notrace __ashrdi3(long long u, word_type b)
{
	DWunion uu, w;
	word_type bm;

	if (b == 0)
		return u;

	uu.ll = u;
	bm = 32 - b;

	if (bm <= 0) {
		/* w.s.high = 1..1 or 0..0 */
		w.s.high =
		    uu.s.high >> 31;
		w.s.low = uu.s.high >> -bm;
	} else {
		const unsigned int carries = (unsigned int) uu.s.high << bm;

		w.s.high = uu.s.high >> b;
		w.s.low = ((unsigned int) uu.s.low >> b) | carries;
	}

	return w.ll;
}
EXPORT_SYMBOL(__ashrdi3);

/* 학습 해설
 * Libgcc 64bit Compare·0·1·2 결과 규약
 * 64bit 비교를 두 32bit word로 나누고 compiler helper의 결과 규약이 일반 비교 callback과 다르다는 점을 배웁니다.
 * Signed __cmpdi2는 먼저 signed high를 비교하고 같으면 unsigned low를 비교합니다. Unsigned __ucmpdi2는 high와 low 모두 unsigned로 비교합니다. 작은 값이면 0, 같은 값이면 1, 큰 값이면 2를 반환합니다. 일반 sort의 음수·0·양수 comparator와 달리 0이 equality를 뜻하지 않습니다. High가 다르면 low를 비교할 필요가 없습니다.
 * libgcc.h의 DWunion과 두 compare 함수를 연결하고 -1·0 비교 및 같은 high/다른 low 예를 추적합니다. 이 helper 결과를 sort callback으로 그대로 반환하지 않습니다. Compiler가 결과 0·1·2를 해석하는 calling convention을 확인합니다.
 */
word_type notrace __cmpdi2(long long a, long long b)
{
	const DWunion au = {
		.ll = a
	};
	const DWunion bu = {
		.ll = b
	};

	if (au.s.high < bu.s.high)
		return 0;
	else if (au.s.high > bu.s.high)
		return 2;

	if ((unsigned int) au.s.low < (unsigned int) bu.s.low)
		return 0;
	else if ((unsigned int) au.s.low > (unsigned int) bu.s.low)
		return 2;

	return 1;
}
EXPORT_SYMBOL(__cmpdi2);

/* 학습 해설
 * Libgcc Multiply·부분 곱과 Carry 합성
 * CPU가 더 작은 단위의 곱셈만 제공해도 큰 정수 곱을 부분 곱과 carry로 구성할 수 있는 원리를 배웁니다.
 * 기본 umul_ppmm은 두 32bit 입력을 각각 16bit high/low로 나누어 네 부분 곱을 만들고 중간 carry를 반영해 64bit product를 구성합니다. __muldi3는 원래 64bit 두 입력의 low×low 결과를 만든 뒤 low×high와 high×low의 교차 항을 결과 high에 더합니다. high×high 항은 64bit 결과 밖이므로 넣지 않습니다. 이 helper의 결과는 128bit 전체 곱을 반환하는 API가 아닙니다.
 * DWunion과 __ll_lowpart/highpart에서 2^16·2^32의 자릿값을 확인합니다. 작은 범위에서 (2^32+1)×2를 high/low로 예측합니다. Kernel compiler 지원 helper의 타입·build arithmetic 규약을 일반 사용자 C의 signed overflow 허용으로 확대하지 않습니다.
 */
long long notrace __muldi3(long long u, long long v)
{
	const DWunion uu = {.ll = u};
	const DWunion vv = {.ll = v};
	DWunion w = {.ll = __umulsidi3(uu.s.low, vv.s.low)};

	w.s.high += ((unsigned long) uu.s.low * (unsigned long) vv.s.high
		+ (unsigned long) uu.s.high * (unsigned long) vv.s.low);

	return w.ll;
}
EXPORT_SYMBOL(__muldi3);

/* 학습 해설
 * Cpumask Wrap·시작점부터 한 바퀴 순회
 * CPU 번호 목록을 한 시작점부터 돌되 시작 CPU가 집합 안에 없어도 각 set bit를 한 번씩 방문하는 순회 원리를 배웁니다.
 * cpumask_next_wrap은 n 다음 set CPU를 찾습니다. 끝에 도달하면 n=-1로 두고 아래 번호부터 다시 찾습니다. Wrap 상태에서 n이 start 아래이고 다음 값이 start 이상이면 한 바퀴를 끝내는 sentinel을 반환합니다. 빈 mask도 wrap 뒤의 시작 경계 검사로 종료합니다. v6.12 header의 for_each_cpu_wrap macro는 실제로 for_each_set_bit_wrap을 사용하므로 이 함수 주석만 보고 macro가 그대로 이 helper를 호출한다고 설명하지 않습니다.
 * 유효 start와 CPU mask에서 {1,4,7}, start=5의 순서를 7·1·4로 예상합니다. 종료 값은 정상 CPU가 아니라 nr_cpu_ids 이상이라는 계약을 확인합니다. CPU 번호의 상한과 set bit 개수는 다르므로 mask의 weight를 최대 번호처럼 쓰지 않습니다.
 */
unsigned int cpumask_next_wrap(int n, const struct cpumask *mask, int start, bool wrap)
{
	unsigned int next;

again:
	next = cpumask_next(n, mask);

	if (wrap && n < start && next >= start) {
		return nr_cpumask_bits;

	} else if (next >= nr_cpumask_bits) {
		wrap = true;
		n = -1;
		goto again;
	}

	return next;
}
EXPORT_SYMBOL(cpumask_next_wrap);

/* These are not inline because of header tangles. */
#ifdef CONFIG_CPUMASK_OFFSTACK
/**
 * alloc_cpumask_var_node - allocate a struct cpumask on a given node
 * @mask: pointer to cpumask_var_t where the cpumask is returned
 * @flags: GFP_ flags
 * @node: memory node from which to allocate or %NUMA_NO_NODE
 *
 * Only defined when CONFIG_CPUMASK_OFFSTACK=y, otherwise is
 * a nop returning a constant 1 (in <linux/cpumask.h>).
 *
 * Return: TRUE if memory allocation succeeded, FALSE otherwise.
 *
 * In addition, mask will be NULL if this fails.  Note that gcc is
 * usually smart enough to know that mask can never be NULL if
 * CONFIG_CPUMASK_OFFSTACK=n, so does code elimination in that case
 * too.
 */

/* 학습 해설
 * Cpumask Distribute·CPU별 선택 Cursor
 * 집합에서 매번 첫 CPU만 골라 일이 집중되는 것을 줄이는 선택 상태와 집합 교차 조건을 익힙니다.
 * Distribute helper는 현재 CPU의 이전 선택값을 읽고 prev+1부터 wrap 검색합니다. and 변형은 두 mask 모두 set인 CPU만 찾습니다. 유효 결과이면 같은 per-CPU cursor를 갱신하고 빈 집합이면 sentinel을 반환하며 cursor를 바꾸지 않습니다. Any와 and 변형은 이 cursor를 공유합니다. 전체 시스템의 전역 round-robin이나 부하 측정이 아니라 호출 CPU별 추천 순회이며 NR_CPUS=1의 header 경로는 단순 첫 CPU 선택입니다.
 * 후보 mask와 허용 CPU mask를 교차해 적합한 CPU를 선택하고 sentinel을 처리합니다. Online CPU가 필요하면 caller가 그 조건을 mask에 넣어야 합니다. 첫 cursor 0에서 mask={0,1,2}이면 최초 선택이 1인 source 주석을 확인하고 호출 CPU가 바뀔 때 상태도 달라질 수 있음을 읽습니다.
 */
unsigned int cpumask_any_and_distribute(const struct cpumask *src1p,
			       const struct cpumask *src2p)
{
	unsigned int next, prev;

	/* NOTE: our first selection will skip 0. */
	prev = __this_cpu_read(distribute_cpu_mask_prev);

	next = find_next_and_bit_wrap(cpumask_bits(src1p), cpumask_bits(src2p),
					nr_cpumask_bits, prev + 1);
	if (next < nr_cpu_ids)
		__this_cpu_write(distribute_cpu_mask_prev, next);

	return next;
}
EXPORT_SYMBOL(cpumask_any_and_distribute);

/**
 * cpumask_any_distribute - Return an arbitrary cpu from srcp
 * @srcp: &cpumask for selection
 *
 * Return: >= nr_cpu_ids if the intersection is empty.
 */
unsigned int cpumask_any_distribute(const struct cpumask *srcp)
{
	unsigned int next, prev;

/* 학습 해설
 * Cpumask Var·설정별 저장 공간과 할당
 * CPU 수가 커질 때 mask를 stack에 항상 올려 놓기보다 커널 설정에 따라 저장 공간을 별도로 확보하는 방식을 배웁니다.
 * CONFIG_CPUMASK_OFFSTACK이면 cpumask_var_t 저장을 kmalloc_node(cpumask_size(),flags,node)로 얻고 실패 시 NULL·false입니다. Header의 zalloc 변형은 __GFP_ZERO를 더해 초기값을 0으로 만듭니다. OFFSTACK이 아니면 이미 포함된 mask 공간을 사용하는 alloc helper는 true만 반환하고 zalloc은 그 공간을 clear합니다. Bootmem 변형은 memblock을 사용하고 할당 실패를 panic으로 처리하므로 runtime boolean 실패 경로와 다릅니다.
 * cpumask_var_t와 alloc/zalloc/free 수명을 사용하고 초기 0이 필요한지에 맞춰 함수를 선택합니다. CPU mask byte 크기를 CPU 개수와 동일하게 계산하지 않습니다. runtime free_cpumask_var와 bootmem free를 맞추고 설정에 따라 storage와 실패 가능성이 달라지는 API를 읽습니다.
 */
bool alloc_cpumask_var_node(cpumask_var_t *mask, gfp_t flags, int node)
{
	*mask = kmalloc_node(cpumask_size(), flags, node);

#ifdef CONFIG_DEBUG_PER_CPU_MAPS
	if (!*mask) {
		printk(KERN_ERR "=> alloc_cpumask_var: failed!\n");
		dump_stack();
	}
#endif

	return *mask != NULL;
}
EXPORT_SYMBOL(alloc_cpumask_var_node);

/**
 * alloc_bootmem_cpumask_var - allocate a struct cpumask from the bootmem arena.
 * @mask: pointer to cpumask_var_t where the cpumask is returned
 *
 * Only defined when CONFIG_CPUMASK_OFFSTACK=y, otherwise is
 * a nop (in <linux/cpumask.h>).
 * Either returns an allocated (zero-filled) cpumask, or causes the
 * system to panic.
 */
void __init alloc_bootmem_cpumask_var(cpumask_var_t *mask)
{

/* 학습 해설
 * Cpumask Local Spread·NUMA 거리 순서
 * 같은 CPU에만 queue를 몰지 않으면서 가까운 NUMA CPU부터 선택하려는 번호 분산 정책을 익힙니다.
 * i를 online CPU 수로 나눈 나머지로 바꾸어 범위를 감고 sched_numa_find_nth_cpu에 cpu_online_mask와 node를 넘깁니다. 지역과 NUMA 거리 정책에 따라 i번째 CPU를 찾습니다. 반환 CPU가 범위 밖이면 WARN을 하지만 자동 fallback CPU를 따로 계산하는 분기는 없습니다. 이 선택은 online mask와 topology 기반이며 현재 가장 한가한 CPU를 측정해서 고르는 함수가 아닙니다.
 * 호출 문맥의 CPU hotplug 일관성과 node 의미를 확인하고 8개 online CPU에서 i=10이 먼저 2로 감기는 것을 계산합니다. 모든 CPU를 반복 나열할 목적이면 source 주석의 NUMA hop mask iterator를 검토합니다. 반환값의 CPU 번호를 i의 나머지 숫자와 같은 것으로 가정하지 않습니다.
 */
unsigned int cpumask_local_spread(unsigned int i, int node)
{
	unsigned int cpu;

	/* Wrap: we always want a cpu. */
	i %= num_online_cpus();

	cpu = sched_numa_find_nth_cpu(cpu_online_mask, i, node);

	WARN_ON(cpu >= nr_cpu_ids);
	return cpu;
}
EXPORT_SYMBOL(cpumask_local_spread);

static DEFINE_PER_CPU(int, distribute_cpu_mask_prev);

/**
 * cpumask_any_and_distribute - Return an arbitrary cpu within src1p & src2p.
 * @src1p: first &cpumask for intersection
 * @src2p: second &cpumask for intersection
 *
 * Iterated calls using the same srcp1 and srcp2 will be distributed within
 * their intersection.
 *
 * Return: >= nr_cpu_ids if the intersection is empty.
 */

/* 학습 해설
 * CPU Groups·NUMA 비례 배분과 Sibling 묶기
 * 장치 queue나 IRQ 그룹에 CPU를 나눌 때 단순 번호 나눗셈 대신 가까운 CPU를 묶고 그룹 크기를 균등하게 만드는 기술을 배웁니다.
 * SMP 구현은 present CPU를 먼저 나누고 나머지 possible CPU를 두 번째 단계에서 나눕니다. Group 수가 NUMA node 수 이하이면 node들을 순환 group에 넣습니다. Group이 더 많으면 CPU가 적은 node부터 정렬하여 남은 group×해당 CPU/남은 CPU의 비율로 group 수를 배분하되 적어도 하나를 줍니다. 한 node 안에서는 몫과 나머지로 group CPU 수를 정하고 sibling CPU를 우선 같이 넣습니다. 각 possible CPU를 덮고 같은 CPU를 여러 group에 중복 배정하지 않는 계약입니다.
 * 양수 numgrps와 실제 possible CPU 수·NUMA 배치를 확인한 뒤 반환 cpumask 배열이나 NULL을 처리합니다. 한 node의 present CPU 8개를 group 3개로 나누는 3·3·2 크기를 계산합니다. 한 group의 CPU가 반드시 현재 online이라는 뜻은 아니며 queue 활성화의 online 조건은 별도로 확인합니다.
 */
struct cpumask *group_cpus_evenly(unsigned int numgrps)
{
	unsigned int curgrp = 0, nr_present = 0, nr_others = 0;
	cpumask_var_t *node_to_cpumask;
	cpumask_var_t nmsk, npresmsk;
	int ret = -ENOMEM;
	struct cpumask *masks = NULL;

	if (!zalloc_cpumask_var(&nmsk, GFP_KERNEL))
		return NULL;

	if (!zalloc_cpumask_var(&npresmsk, GFP_KERNEL))
		goto fail_nmsk;

	node_to_cpumask = alloc_node_to_cpumask();
	if (!node_to_cpumask)
		goto fail_npresmsk;

	masks = kcalloc(numgrps, sizeof(*masks), GFP_KERNEL);
	if (!masks)
		goto fail_node_to_cpumask;

	build_node_to_cpumask(node_to_cpumask);

	/*
	 * Make a local cache of 'cpu_present_mask', so the two stages
	 * spread can observe consistent 'cpu_present_mask' without holding
	 * cpu hotplug lock, then we can reduce deadlock risk with cpu
	 * hotplug code.
	 *
	 * Here CPU hotplug may happen when reading `cpu_present_mask`, and
	 * we can live with the case because it only affects that hotplug
	 * CPU is handled in the 1st or 2nd stage, and either way is correct
	 * from API user viewpoint since 2-stage spread is sort of
	 * optimization.
	 */

/* 학습 해설
 * Jenkins Jhash·세 Word의 Mix와 Final
 * 네트워크 등의 해시 테이블에서 길이와 여러 입력 word를 섞는 빠른 비암호 해시의 준비·본체·꼬리 처리를 배웁니다.
 * a·b·c를 0xdeadbeef+길이+initval로 시작합니다. 12바이트보다 큰 남은 구간에서는 세 32bit word를 더하고 rotate·XOR·덧셈·뺄셈의 mix를 수행합니다. 마지막 1~12바이트는 switch fallthrough로 a/b/c에 넣고 final로 c를 섞습니다. 길이 0은 final 없이 초기 c를 반환합니다. jhash2의 length는 byte가 아니라 u32 원소 수이고 word 전용 helper는 대응 byte 길이를 초기값에 넣습니다. 출력은 32bit이며 원본은 byte 버전의 endian 의존성을 명시합니다.
 * byte buffer에는 jhash, u32 배열에는 jhash2의 길이 단위를 맞춥니다. 테이블 생애 동안 initval을 일관되게 쓰고 변경 시 저장·조회가 같은 규약을 따르도록 합니다. Seed가 있다는 사실만으로 SipHash 같은 keyed 보안 보장이 되는 것은 아닙니다. Hash 충돌 후 실제 key를 비교합니다.
 */
static inline u32 jhash(const void *key, u32 length, u32 initval)
{
	u32 a, b, c;
	const u8 *k = key;

	/* Set up the internal state */
	a = b = c = JHASH_INITVAL + length + initval;

	/* All but the last block: affect some 32 bits of (a,b,c) */
	while (length > 12) {
		a += __get_unaligned_cpu32(k);
		b += __get_unaligned_cpu32(k + 4);
		c += __get_unaligned_cpu32(k + 8);
		__jhash_mix(a, b, c);
		length -= 12;
		k += 12;
	}
	/* Last block: affect all 32 bits of (c) */
	switch (length) {
	case 12: c += (u32)k[11]<<24;	fallthrough;
	case 11: c += (u32)k[10]<<16;	fallthrough;
	case 10: c += (u32)k[9]<<8;	fallthrough;
	case 9:  c += k[8];		fallthrough;
	case 8:  b += (u32)k[7]<<24;	fallthrough;
	case 7:  b += (u32)k[6]<<16;	fallthrough;
	case 6:  b += (u32)k[5]<<8;	fallthrough;

/* 학습 해설
 * UUID·GUID Parse·문자와 Byte 순서
 * 파일시스템·firmware 식별자를 문자열에서 읽을 때 같은 표시 문자열도 UUID와 GUID의 저장 byte 순서가 다를 수 있음을 배웁니다.
 * uuid_is_valid는 앞 36개 위치의 16진수 문자와 8·13·18·23 위치 hyphen을 확인합니다. __uuid_parse는 각 hex pair를 byte로 바꾸고 ei index에 저장합니다. UUID index는 0~15 순서이고 GUID는 처음 4byte·다음 2byte·다음 2byte의 순서를 각각 뒤집습니다. 이후 8byte는 그대로입니다. Parser는 UUID version/variant의 유효성이나 36번 위치의 문자열 종료를 별도로 검사하지 않습니다.
 * 장치가 UUID/GUID 중 어떤 byte 표현을 요구하는지 확인하고 해당 parse helper를 골라 0 성공과 EINVAL을 처리합니다. 완전한 36문자 문자열을 기대하는 caller는 길이·뒤 문자 정책도 확인합니다. 00112233-4455-6677-8899-aabbccddeeff의 앞 byte를 두 형식으로 적어 비교합니다.
 */
int uuid_parse(const char *uuid, uuid_t *u)
{
	return __uuid_parse(uuid, u->b, uuid_index);
}
EXPORT_SYMBOL(uuid_parse);

/* 학습 해설
