/* 학습 해설
 * Kasprintf·두 번 계산하는 문자열 할당
 * 형식 문자열의 결과 길이를 미리 모를 때 크기를 구한 다음 정확한 저장 공간을 할당하는 방법을 배웁니다.
 * kvasprintf는 va_copy로 인자 목록의 복사본을 만들고 vsnprintf(NULL,0,fmt,aq)로 필요 길이를 구한 뒤 va_end합니다. first+1바이트를 kmalloc_track_caller로 할당하고 원래 ap를 사용해 다시 출력합니다. 할당 실패는 NULL이며 두 계산 길이가 다르면 WARN을 출력합니다. kasprintf는 가변 인자의 va_start·va_end를 관리하고 이 helper를 호출합니다.
 * 허용된 kernel format과 정확한 인자 타입을 사용하며 GFP의 잠들 수 있는 문맥을 맞춥니다. 반환 NULL을 확인하고 성공 결과는 kfree합니다. 두 출력 사이에 참조하는 문자열이 바뀌지 않도록 안정된 입력 수명을 확보합니다. Kernel vsnprintf의 pointer 확장 문법은 사용자 libc와 같지 않을 수 있습니다.
 */
char *kvasprintf(gfp_t gfp, const char *fmt, va_list ap)
{
	unsigned int first, second;
	char *p;
	va_list aq;

	va_copy(aq, ap);
	first = vsnprintf(NULL, 0, fmt, aq);
	va_end(aq);

	p = kmalloc_track_caller(first+1, gfp);
	if (!p)
		return NULL;

	second = vsnprintf(p, first+1, fmt, ap);
	WARN(first != second, "different return values (%u and %u) from vsnprintf(\"%s\", ...)",
	     first, second, fmt);

	return p;
}
EXPORT_SYMBOL(kvasprintf);

/*
 * If fmt contains no % (or is exactly %s), use kstrdup_const. If fmt
 * (or the sole vararg) points to rodata, we will then save a memory
 * allocation and string copy. In any case, the return value should be
 * freed using kfree_const().
 */

/* 학습 해설
 * Const 형식 문자열·복사 생략과 해제 계약
 * 읽기 전용 상수 문자열을 새로 복사하지 않는 최적화에서는 반환값을 항상 일반 heap 객체처럼 해제할 수 없습니다.
 * fmt에 %가 없으면 kstrdup_const(fmt,gfp)로 처리합니다. fmt가 정확히 %s이면 va_arg로 얻은 문자열을 kstrdup_const에 전달합니다. 그 밖의 형식은 kvasprintf로 새 출력 공간을 만듭니다. kstrdup_const는 rodata인 경우 원래 상수 주소를 유지할 수 있고 다른 경우 복사본을 만들 수 있으므로 모든 경로의 결과는 kfree_const 계약으로 해제해야 합니다.
 * 반환 NULL을 확인하고 const char*로 읽으며 수정 가능한 배열처럼 쓰지 않습니다. 정확한 %s와 prefix가 붙은 name=%s를 구분합니다. caller는 va_list를 올바르게 시작하고 정리해야 하며 반환이 const 최적화 경로인지 추측해 일반 kfree를 선택하지 않습니다.
 */
const char *kvasprintf_const(gfp_t gfp, const char *fmt, va_list ap)
{
	if (!strchr(fmt, '%'))
		return kstrdup_const(fmt, gfp);
	if (!strcmp(fmt, "%s"))
		return kstrdup_const(va_arg(ap, const char*), gfp);
	return kvasprintf(gfp, fmt, ap);
}
EXPORT_SYMBOL(kvasprintf_const);

char *kasprintf(gfp_t gfp, const char *fmt, ...)
{
	va_list ap;
	char *p;

	va_start(ap, fmt);
	p = kvasprintf(gfp, fmt, ap);
	va_end(ap);

	return p;
}
EXPORT_SYMBOL(kasprintf);

