/* 학습 해설
 * Partial Checksum·조각 누적과 접기
 * 흩어진 packet 자료를 한 번에 복사하지 않고 순서대로 합산할 때 중간 합의 표현과 조각 경계 조건이 필요합니다.
 * csum_partial은 do_csum의 합에 기존32bit wsum을 더하고 overflow carry를1로 회수해 __wsum을 반환합니다. 최종16bit checksum으로 보수를 적용한 결과와 달리 다음 partial 누적이나 TCP/UDP pseudo-header에 넘기는 중간값입니다. 원본 계약은 마지막 조각을 제외한 호출 길이가 짝수여야 한다고 명시합니다. Generic csum_fold는 중간합을16bit로 접고 보수로 바꿉니다.
 * sum=0부터 짝수 길이 조각을 순서대로 csum_partial에 전달하고 마지막에 한 번 csum_fold합니다. 마지막만 홀수일 수 있습니다. 임의 byte 경계의 scatter fragment는 checksum block offset을 보정하는 다른 helper 계약까지 확인해야 하며 단순 partial 반복을 모든 분할에 일반화하지 않습니다.
 */
__wsum csum_partial(const void *buff, int len, __wsum wsum)
{
	unsigned int sum = (__force unsigned int)wsum;
	unsigned int result = do_csum(buff, len);

	/* add in old sum, and carry.. */
	result += sum;
	if (sum > result)
		result += 1;
	return (__force __wsum)result;
}
EXPORT_SYMBOL(csum_partial);

/*
 * this routine is used for miscellaneous IP-like checksums, mainly
 * in icmp.c
 */
__sum16 ip_compute_csum(const void *buff, int len)
{
	return (__force __sum16)~do_csum(buff, len);
}
EXPORT_SYMBOL(ip_compute_csum);

