#ifndef __HAVE_ARCH_STRNCMP
/**
 * strncmp - Compare two length-limited strings
 * @cs: One string
 * @ct: Another string
 * @count: The maximum number of bytes to compare
 */
int strncmp(const char *cs, const char *ct, size_t count)
{

/* 학습 해설
 * 대소문자 비교·Byte 변환과 종료
 * 대소문자만 다른 kernel option 이름을 비교할 때 ASCII 계열 문자 변환과 제한 길이의 실제 동작을 읽습니다.
 * strncasecmp는 len=0이면0입니다. 각 byte를 unsigned로 읽고 NUL이 있으면 멈추며 원래 byte가 같으면 다음으로 넘어갑니다. 다르면 tolower로 변환해 비교하고 최종 c1-c2를 반환합니다. strcasecmp는 NUL까지 tolower 비교를 계속합니다. 두 함수는 byte 문자 변환이며 UTF8 여러 byte의 Unicode case folding이나 locale 정렬을 수행하지 않습니다.
 * 실제 Linux ctype 변환 규약에 맞는 ASCII 설정 이름을 제공하고 비교 결과의 부호를 사용합니다. 길이 제한의 prefix equality와 전체 이름 equality를 구분합니다. Byte 자료에 포함된 NUL은 비교를 종료시킵니다.
 */
int strncasecmp(const char *s1, const char *s2, size_t len)
{
	/* Yes, Virginia, it had better be unsigned */
	unsigned char c1, c2;

	if (!len)
		return 0;

	do {
		c1 = *s1++;
		c2 = *s2++;
		if (!c1 || !c2)
			break;
		if (c1 == c2)
			continue;
		c1 = tolower(c1);
		c2 = tolower(c2);
		if (c1 != c2)
			break;
	} while (--len);
	return (int)c1 - (int)c2;
}
EXPORT_SYMBOL(strncasecmp);
#endif

